cat > src/money.ts <<'EOF'
export function formatAmount(cents: number): string {
  const sign = cents < 0 ? '-' : ''; const absolute = Math.abs(cents);
  return sign + Math.floor(absolute / 100) + '.' + String(absolute % 100).padStart(2, '0');
}
EOF
python3 - <<'PY'
from pathlib import Path
for name, old in [('invoice', 'invoiceAmount'), ('report', 'reportAmount')]:
    p = Path('src') / (name + '.ts')
    p.write_text(p.read_text().replace(old, 'formatAmount').replace("from './formatAmount'", "from './money'"))
    (Path('src') / (old + '.ts')).unlink()
PY
cat >> checks/public.cjs <<'EOF'

const { formatAmount } = require('../.build/money');
for (const [cents, expected] of [
  [0, '0.00'], [-0, '0.00'], [1, '0.01'], [-1, '-0.01'],
  [99, '0.99'], [-99, '-0.99'], [100, '1.00'], [-100, '-1.00'],
  [123, '1.23'], [-123, '-1.23'], [12345, '123.45'], [-12345, '-123.45'],
]) {
  assert.equal(formatAmount(cents), expected);
  assert.equal(renderInvoice('inv', cents), 'inv: $' + expected);
  assert.equal(renderReport([{ id: 'row', cents }]), 'row,' + expected);
}
assert.equal(renderReport([]), '');
assert.equal(
  renderReport([{ id: 'z', cents: 123 }, { id: 'a', cents: -100 }, { id: 'm', cents: 0 }]),
  'z,1.23\na,-1.00\nm,0.00',
);
EOF
tsc -p tsconfig.json && node checks/public.cjs
cat src/invoice.ts src/report.ts; grep -R -nE 'invoiceAmount|reportAmount' src || true

